@namespace sv_06805817096947089fc25fb2342ba328.Components.Pages.Settings
@using sv_06805817096947089fc25fb2342ba328.Services
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-body">
        <h4 class="card-title mb-4">Security</h4>

        @if (_loading)
        {
            <div class="text-center p-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <!-- Change Password Panel -->
            <div class="mb-4">
                <div class="d-flex align-items-center mb-2">
                    <h6 class="mb-0">Change Password</h6>
                    <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="() => _passwordExpanded = !_passwordExpanded">
                        @(_passwordExpanded ? "Collapse" : "Expand")
                    </button>
                </div>
                @if (_passwordExpanded)
                {
                    <div class="border rounded p-3">
                        <div class="mb-2">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-2">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                            @if (_changingPassword)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="mb-4">
                <h6>Two-Factor Authentication</h6>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-1">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
                }
            </div>

            <!-- Active Sessions -->
            <div>
                <h6>Active Sessions</h6>
                @if (_sessions.Count == 0)
                {
                    <p class="text-muted">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-sm table-hover">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != _sessions.First())
                                            {
                                                @if (_confirmRevokeId == session.Id)
                                                {
                                                    <span class="me-1">Revoke?</span>
                                                    <button class="btn btn-sm btn-danger me-1" @onclick="() => RevokeSessionAsync(session.Id)">Yes</button>
                                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => _confirmRevokeId = null">No</button>
                                                }
                                                else
                                                {
                                                    <button class="btn btn-sm btn-outline-danger" @onclick="() => _confirmRevokeId = session.Id">Revoke</button>
                                                }
