@namespace sv_06805817096947089fc25fb2342ba328.Components.Pages.Settings
@using sv_06805817096947089fc25fb2342ba328.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance</h4>

        @if (_loading)
        {
            <div class="text-center p-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-6">
                    <!-- Theme -->
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <!-- Font Size -->
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                                       value="@size" checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"size-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <!-- Language -->
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @if (_saving)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Save
                    </button>
                </div>

                <!-- Live Preview -->
                <div class="col-md-6">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @PreviewBackgroundClass" style="@PreviewStyle">
                        <h5 style="@PreviewFontStyle">Sample Heading</h5>
                        <p style="@PreviewFontStyle" class="@(PreviewTextClass) @(_compactMode ? "mb-1" : "mb-3")">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2 @(_compactMode ? "flex-wrap" : "")">
                            <button class="btn btn-sm @PreviewButtonClass">Action</button>
                            <span class="badge @PreviewBadgeClass align-self-center">Badge</span>
                        </div>
                        <small class="@PreviewMutedClass d-block mt-2">
                            Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")
                        </small>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewStyle => _theme == "Dark" ? "color: #e0e0e0;" : "";

    private string PreviewBackgroundClass => _theme switch
    {
        "Dark" => "bg-dark",
        "System" => "bg-body-secondary",
        _ => "bg-light"
    };

    private string PreviewTextClass => _theme == "Dark" ? "text-light" : "text-dark";
    private string PreviewMutedClass => _theme == "Dark" ? "text-light opacity-50" : "text-muted";
    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-primary";
}

